import{_ as a,o as t,c as e,a4 as c}from"./chunks/framework.DCsBdTIw.js";const f=JSON.parse('{"title":"语言服务器概览","description":"clice 提供一套基于 LLVM/Clang 构建的 C++ 开发工具。本节按功能逐一介绍 clice 的能力，以及每项功能解决的 clangd 问题。","frontmatter":{"head":[["meta",{"property":"og:title","content":"语言服务器概览 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/features/overview"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/features/overview"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/features/overview"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/features/overview"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/features/overview"}],["meta",{"property":"og:description","content":"clice 提供一套基于 LLVM/Clang 构建的 C++ 开发工具。本节按功能逐一介绍 clice 的能力，以及每项功能解决的 clangd 问题。"}]]},"headers":[],"relativePath":"zh/clice/features/overview.md","filePath":"zh/clice/features/overview.md","lastUpdated":1795572204000}'),l={name:"zh/clice/features/overview.md"};function n(r,s,o,i,p,d){return t(),e("div",null,[...s[0]||(s[0]=[c('<h1 id="language-server-overview" tabindex="-1"><span id="语言服务器概览" class="heading-alias"></span>语言服务器概览 <a class="header-anchor" href="#language-server-overview" aria-label="Permalink to &quot;语言服务器概览&quot;">​</a></h1><p>clice 提供一套基于 LLVM/Clang 构建的 C++ 开发工具。本节按功能逐一介绍 clice 的能力，以及每项功能解决的 clangd 问题。</p><h2 id="languages" tabindex="-1"><span id="语言" class="heading-alias"></span>语言 <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;语言&quot;">​</a></h2><p>clice 支持 C、C++、CUDA、HIP 和 OpenCL；对 Objective-C 和 Objective-C++，则支持代码阅读功能：语义 Token、悬停、代码导航与查找引用、调用层次结构与类型层次结构、大纲、折叠范围、工作区符号以及 <code>clice query</code> 均能识别其中的类、协议、分类（category）、方法、属性和实例变量，代码补全能写出消息的选择器（selector），重命名支持类、协议、分类和实例变量。不支持重命名方法或属性，也不支持 Clang 头文件模块（<code>-fmodules</code>、<code>@import</code>）：文件会在不启用头文件模块的情况下编译，clice 对此只提示一次。与其他项目一样，Objective-C 项目也需要编译数据库；CMake 的 Makefile 和 Ninja 生成器会生成它，而 Xcode 和 CMake 的 Xcode 生成器都不会。</p><p>CUDA 和 HIP 文件编译的是设备端代码，因为 Clang 会先执行这一步。OpenCL C 和 C++ for OpenCL（<code>.cl</code>、<code>.clcpp</code>）直接按 Clang 的方式编译，内建函数也都可用；编译数据库未列出的文件采用规则的 <code>default_command</code>，例如 <code>clang -cl-std=CL3.0</code>。VS Code 本身没有内置这些语言，VS Code 扩展会为 <code>.hip</code> 提供 <code>hip</code> 语言，为各 OpenCL 扩展名提供 <code>opencl</code> 语言；<code>.cl</code> 同时也是 Common Lisp 的扩展名，可用 <code>files.associations</code> 改回。</p><h2 id="features" tabindex="-1"><span id="功能" class="heading-alias"></span>功能 <a class="header-anchor" href="#features" aria-label="Permalink to &quot;功能&quot;">​</a></h2><p>将 clice 用作编辑器后端时可用的语言服务器协议（LSP）功能。</p><table tabindex="0"><thead><tr><th>功能</th><th>状态</th></tr></thead><tbody><tr><td><a href="./completion">代码补全</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:55;"></i><i class="warn" style="flex:1;"></i></span><span class="counts"><b class="ok">支持 55 项</b><b class="warn">部分支持 1 项</b></span></span></td></tr><tr><td><a href="./hover">悬停</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:72;"></i></span><span class="counts"><b class="ok">支持 72 项</b></span></span></td></tr><tr><td><a href="./signature-help">签名帮助</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:21;"></i><i class="warn" style="flex:1;"></i><i class="no" style="flex:2;"></i></span><span class="counts"><b class="ok">支持 21 项</b><b class="warn">部分支持 1 项</b><b class="no">不支持 2 项</b></span></span></td></tr><tr><td><a href="./navigation">代码导航</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:125;"></i><i class="warn" style="flex:1;"></i><i class="no" style="flex:6;"></i></span><span class="counts"><b class="ok">支持 125 项</b><b class="warn">部分支持 1 项</b><b class="no">不支持 6 项</b></span></span></td></tr><tr><td><a href="./rename">重命名</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:9;"></i></span><span class="counts"><b class="ok">支持 9 项</b></span></span></td></tr><tr><td><a href="./diagnostics">诊断</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:12;"></i><i class="warn" style="flex:1;"></i></span><span class="counts"><b class="ok">支持 12 项</b><b class="warn">部分支持 1 项</b></span></span></td></tr><tr><td><a href="./code-action">代码操作</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:45;"></i></span><span class="counts"><b class="ok">支持 45 项</b></span></span></td></tr><tr><td><a href="./semantic-tokens">语义 Token</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:61;"></i></span><span class="counts"><b class="ok">支持 61 项</b></span></span></td></tr><tr><td><a href="./inlay-hints">内联提示</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:40;"></i></span><span class="counts"><b class="ok">支持 40 项</b></span></span></td></tr><tr><td><a href="./document-links">文档链接</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:5;"></i><i class="warn" style="flex:1;"></i></span><span class="counts"><b class="ok">支持 5 项</b><b class="warn">部分支持 1 项</b></span></span></td></tr><tr><td><a href="./document-symbols">文档符号</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:29;"></i></span><span class="counts"><b class="ok">支持 29 项</b></span></span></td></tr><tr><td><a href="./folding-ranges">折叠范围</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:24;"></i></span><span class="counts"><b class="ok">支持 24 项</b></span></span></td></tr><tr><td><a href="./selection-ranges">选择范围</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:14;"></i></span><span class="counts"><b class="ok">支持 14 项</b></span></span></td></tr><tr><td><a href="./formatting">格式化</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:4;"></i></span><span class="counts"><b class="ok">支持 4 项</b></span></span></td></tr><tr><td><a href="./modules">C++20 模块</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:9;"></i></span><span class="counts"><b class="ok">支持 9 项</b></span></span></td></tr><tr><td><a href="./header-contexts">头文件上下文</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:6;"></i></span><span class="counts"><b class="ok">支持 6 项</b></span></span></td></tr><tr><td><a href="./compilation">编译</a></td><td><span class="status-bar"><span class="track"><i class="ok" style="flex:9;"></i></span><span class="counts"><b class="ok">支持 9 项</b></span></span></td></tr></tbody></table><h2 id="legend" tabindex="-1"><span id="图例" class="heading-alias"></span>图例 <a class="header-anchor" href="#legend" aria-label="Permalink to &quot;图例&quot;">​</a></h2><p>每项功能按状态统计其页面中记录的能力数量：</p><ul><li><strong>支持</strong>——该能力可用；快照（snapshot）锁定其行为</li><li><strong>部分支持</strong>——部分可用；快照锁定其中可用的部分</li><li><strong>不支持</strong>——已记录的功能缺口；快照锁定 clice 的替代行为</li></ul>',11)])])}const h=a(l,[["render",n]]);export{f as __pageData,h as default};
